import {readFileSync} from 'node:fs';
import vm from 'node:vm';
import assert from 'node:assert/strict';
import test from 'node:test';
test('custom reference upload waits for an explicit analysis action',()=>{const {ctx,app}=setup();ctx.testInput={files:[{name:'reference.png',type:'image/png',size:100}],setAttribute(){},remove(){},click(){this.onchange();}};ctx.document.body={append(){}};ctx.document.createElement=tag=>tag==='input'?ctx.testInput:{getContext:()=>({drawImage(){}}),toDataURL:()=> 'data:image/png;base64,demo'};ctx.FileReader=class {readAsDataURL(){this.result='data:image/png;base64,demo';this.onload();}};ctx.Image=class {width=800;height=600;set src(v){this.onload();}};vm.runInContext("s.step=5;let calls=0;analyzeReference=async()=>{calls++};act('ref-upload','')",ctx);assert.equal(vm.runInContext('calls',ctx),0);assert.equal(vm.runInContext('s.reference.analysis.status',ctx),'idle');assert.equal(vm.runInContext('simpleTemplateReady()',ctx),false);assert.match(app.innerHTML,/分析参考图/);assert.match(app.innerHTML,/上传参考图 → 分析风格 → 选择商品/);});
test('uploaded reference analysis shows results and unlocks products without extra confirmation',async()=>{const {ctx,app}=setup();vm.runInContext("s.step=5;Object.assign(Ref.ensure(s),{source:'upload',name:'custom.png',image:'data:fixture',analysis:{status:'idle',kind:'demo'}});render()",ctx);await vm.runInContext("act('simple-next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),5);await vm.runInContext("act('ref-analyze','')",ctx);assert.equal(vm.runInContext('simpleTemplateReady()',ctx),true);assert.match(app.innerHTML,/风格分析结果/);assert.match(app.innerHTML,/与上传图片内容无关/);assert.match(app.innerHTML,/使用此风格，选商品/);await vm.runInContext("act('simple-next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),3);});
test('a second generation retains a recoverable version and export uses the generated state',async()=>{const {ctx}=setup();vm.runInContext("s.step=3;s.items[5].price=36;Ref.choose(s,'collage');Ref.finishAnalysis(s)",ctx);await vm.runInContext('simpleGenerate()',ctx);vm.runInContext("s.exportWarning=true;s.format='png';s.filename='test-menu'",ctx);assert.equal(vm.runInContext('exportAllowed()',ctx),true);await vm.runInContext('simpleGenerate()',ctx);assert.equal(vm.runInContext('s.compositionVariant',ctx),1);assert.equal(vm.runInContext('s.previousDesign.compositionVariant',ctx),0);await vm.runInContext("act('simple-restore','')",ctx);assert.equal(vm.runInContext('s.compositionVariant',ctx),0);assert.equal(vm.runInContext('s.generated',ctx),true);});
function setup(){const app={innerHTML:''},main={scrollTop:0,scrollTo(){}},dialog={close(){},showModal(){}},ctx=vm.createContext({console,structuredClone,URL,setTimeout,clearTimeout,document:{querySelector(k){return k==='#app'?app:k==='.main'?main:k==='#dialog'?dialog:null},addEventListener(){}},localStorage:{getItem:()=>null,setItem(){}}});ctx.window=ctx;ctx.addEventListener=()=>{};for(const f of ['model.js','menu-renderer.js','menu-layouts.js','reference-design.js','brand-materials.js','studio.js','reference-controller.js','simple-flow.js'])vm.runInContext(readFileSync(new URL(f,import.meta.url),'utf8'),ctx);vm.runInContext('toast=()=>{};home=false',ctx);return {ctx,app};}
test('three inputs replace the eight-step rail and preserve legacy materials',()=>{const {ctx,app}=setup();vm.runInContext("s.step=4;s.items[0].image='data:real';Ref.choose(s,'grid');Ref.finishAnalysis(s);simpleNormalize();render()",ctx);assert.equal(vm.runInContext('s.step',ctx),3);assert.equal(vm.runInContext('s.items[0].image',ctx),'data:real');assert.match(app.innerHTML,/选择商品/);assert.doesNotMatch(app.innerHTML,/data-action="goto" data-id="4"/);assert.match(app.innerHTML,/更多设置/);});
test('specification goes directly to templates then products without analysis confirmation',async()=>{const {ctx}=setup();await vm.runInContext("act('simple-next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),5);await vm.runInContext("act('simple-template','collage')",ctx);await vm.runInContext("act('simple-next','')",ctx);assert.equal(vm.runInContext('s.step',ctx),3);assert.equal(vm.runInContext('s.density',ctx),4);});
test('missing price blocks generation without fabricating a value',async()=>{const {ctx,app}=setup();vm.runInContext("s.step=3;Ref.choose(s,'hero');Ref.finishAnalysis(s)",ctx);await vm.runInContext('simpleGenerate()',ctx);assert.equal(vm.runInContext('s.generated',ctx),false);assert.equal(vm.runInContext('s.items[5].price',ctx),null);assert.match(app.innerHTML,/请确认价格/);});
test('generation automatically paginates and reaches editor and export',async()=>{const {ctx}=setup();vm.runInContext("s.step=3;s.items[5].price=36;Ref.choose(s,'hero');Ref.finishAnalysis(s)",ctx);await vm.runInContext('simpleGenerate()',ctx);assert.equal(vm.runInContext('s.step',ctx),7);assert.equal(vm.runInContext('s.generated',ctx),true);assert.equal(vm.runInContext('M.pages(s).length',ctx),3);assert.equal(vm.runInContext('Ref.ready(s)',ctx),true);assert.equal(vm.runInContext('s.noImage',ctx),true);await vm.runInContext("act('simple-export','')",ctx);assert.equal(vm.runInContext('s.step',ctx),8);});
test('cancellation and failure preserve the current project',async()=>{const {ctx}=setup();vm.runInContext("s.step=3;s.items[5].price=36;Ref.choose(s,'grid');Ref.finishAnalysis(s)",ctx);const p=vm.runInContext('simpleGenerate()',ctx);await vm.runInContext("act('cancel-job','')",ctx);await p;assert.equal(vm.runInContext('s.generated',ctx),false);vm.runInContext('failGenerate=true',ctx);await vm.runInContext('simpleGenerate()',ctx);assert.equal(vm.runInContext('s.generated',ctx),false);assert.equal(vm.runInContext('M.items(s).length',ctx),12);});
